import numpy as np
def mgs(A):
    A = A.astype(float).copy(); m, n = A.shape
    Q = np.zeros((m, n)); R = np.zeros((n, n))
    for j in range(n):
        v = A[:, j].copy()
        for i in range(j):
            R[i, j] = Q[:, i] @ v; v -= R[i, j] * Q[:, i]
        R[j, j] = np.linalg.norm(v); Q[:, j] = v / R[j, j]
    return Q, R

import numpy as np
def is_pos_def(A):
    try:
        np.linalg.cholesky(A); return True
    except np.linalg.LinAlgError:
        return False
print(is_pos_def(np.array([[2.0, -1.0], [-1.0, 2.0]])))   # True
